                        break

    base = [row[:] for row in g]
    colors = {v for row in base for v in row if v not in (0, 2, 4)}

    # Complete every same-color straight span. At crossings, horizontal
    # strokes are drawn last.
    vertical = []
    horizontal = []
    for color in colors:
        for c in range(w):
